CREATE TABLE IF NOT EXISTS warehouse_bay_events (
  id SERIAL PRIMARY KEY,
  bay_id INTEGER NOT NULL,
  bay_name VARCHAR(100) NOT NULL,
  workflow_id INTEGER,
  event VARCHAR(20) NOT NULL,
  robot_company VARCHAR(255),
  show_name VARCHAR(255),
  notes TEXT,
  "createdAt" TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_warehouse_bay_events_bay_id ON warehouse_bay_events(bay_id);
CREATE INDEX IF NOT EXISTS idx_warehouse_bay_events_workflow_id ON warehouse_bay_events(workflow_id);
CREATE INDEX IF NOT EXISTS idx_warehouse_bay_events_created_at ON warehouse_bay_events("createdAt");

